+using Infrastructure;
+using Microsoft.EntityFrameworkCore;
+using OpenAuth.App.Finance.Interfaces;
+using OpenAuth.App.Finance.Request;
+using OpenAuth.App.Finance.Response;
+using OpenAuth.App.Interface;
+using OpenAuth.Repository.Domain;
+using OpenAuth.Repository.Domain.Settlement;
+using OpenAuth.Repository.Interface;
+using System;
+using System.Collections.Generic;
+using System.Linq;
+using System.Threading.Tasks;
+
+namespace OpenAuth.App.Finance
+{
+    /// <summary>
+    /// 每日逾期快照查询服务
+    /// </summary>
+    public class DailyOverdueSnapshotApp : OnlyUnitWorkBaeApp, IDailyOverdueSnapshotApp
+    {
+        private readonly ServiceBaseApp _serviceBaseApp;
+        private const string view_all = "view_all";
+        private const string view_dept = "view_dept";
+        private const string view_self = "view_self";
+        /// <summary>
+        /// 构造函数
+        /// </summary>
+        public DailyOverdueSnapshotApp(IUnitWork unitWork, IAuth auth, ServiceBaseApp serviceBaseApp) : base(unitWork, auth)
+        {
+            _serviceBaseApp = serviceBaseApp;
+        }
+
+        /// <summary>
+        /// 获取逾期快照柱状图数据（按销售员分组）
+        /// </summary>
+        public async Task<OverdueAgingChartWrapper> GetOverdueAgingSnapshotChart(OverdueAgingSnapshotReq req)
+        {
+            var snapshotDate = req.AgingDate.Date;
+            var query = UnitWork.Find<DailyOverdueSnapshot>(x => x.PostingDate == snapshotDate);
+
+            if (req.SlpCodes?.Any() == true)
+                query = query.Where(x => x.SlpCode.HasValue && req.SlpCodes.Contains(x.SlpCode.Value.ToString()));
+
+            var snapshots = await query.ToListAsync();
+
+            var data = snapshots
+                .GroupBy(x => x.SlpName)
+                .Select(g =>
+                {
+                    var resp = new OverdueAgingChartResp { Salesman = g.Key };
+                    var buckets = new decimal[6];
+                    foreach (var item in g)
+                    {
+                        var bucket = GetSnapshotBucket(item.OverdueDays, req);
+                        buckets[bucket] += item.DueBalance;
+                        resp.Total += item.DueBalance;
+                    }
+                    resp.Bucket1 = buckets[1];
+                    resp.Bucket2 = buckets[2];
+                    resp.Bucket3 = buckets[3];
+                    resp.Bucket4 = buckets[4];
+                    resp.Bucket5 = buckets[5];
+                    return resp;
+                })
+                .OrderByDescending(x => x.Total)
+                .Take(req.Top)
+                .ToList();
+
+            var columnHeaders = GenerateSnapshotColumnHeaders(req);
+
+            return new OverdueAgingChartWrapper
+            {
+                ColumnHeaders = columnHeaders,
+                Data = data
+            };
+        }
+
+        /// <summary>
+        /// 获取逾期快照详情数据（按销售员+客户分组，分页）
+        /// </summary>
+        public async Task<OverdueAgingDetailWrapper> GetOverdueAgingSnapshotDetail(OverdueAgingSnapshotDetailReq req)
+        {
+            var snapshotDate = req.AgingDate.Date;
+            var query = UnitWork.Find<DailyOverdueSnapshot>(x => x.PostingDate <= snapshotDate);
+
+            if (req.SlpCodes?.Any() == true)
+                query = query.Where(x => x.SlpCode.HasValue && req.SlpCodes.Contains(x.SlpCode.Value.ToString()));
+
+            // 每个订单只取截止日期前最新的一条快照，代表该订单在截止日时的逾期状态
+            var snapshots = (await query.ToListAsync())
+                .GroupBy(x => x.DocEntry)
+                .Select(g => g.OrderByDescending(x => x.PostingDate).First())
+                .ToList();
+
+            if (!string.IsNullOrEmpty(req.Salesman))
+                snapshots = snapshots.Where(x => x.SlpName == req.Salesman).ToList();
+
+            // 按(销售员, 客户)分组，每条记录根据OverdueDays确定账龄档位后汇总
+            var grouped = snapshots
+                .Select(item => new
+                {
+                    item.SlpName,
+                    item.CustomerCode,
+                    item.CustomerName,
+                    item.DueBalance,
+                    Bucket = GetSnapshotBucket(item.OverdueDays, req)
+                })
+                .GroupBy(x => new { x.SlpName, x.CustomerCode })
+                .Select(g =>
+                {
+                    var buckets = new decimal[6];
+                    decimal total = 0m;
+                    string customerName = g.First().CustomerName;
+                    foreach (var item in g)
+                    {
+                        buckets[item.Bucket] += item.DueBalance;
+                        total += item.DueBalance;
+                    }
+                    return new OverdueAgingDetailResp
+                    {
+                        Salesman = g.Key.SlpName,
+                        CustomerCode = g.Key.CustomerCode,
+                        CustomerName = customerName,
+                        DueBalance = total,
+                        Bucket1 = buckets[1],
+                        Bucket2 = buckets[2],
+                        Bucket3 = buckets[3],
+                        Bucket4 = buckets[4],
+                        Bucket5 = buckets[5]
+                    };
+                })
+                .Where(x => x.DueBalance != 0m)
+                .ToList();
+
+            var salesmanTotals = grouped
+                .GroupBy(x => x.Salesman)
+                .ToDictionary(g => g.Key, g => g.Sum(x => x.DueBalance));
+
+            var sorted = grouped
+                .OrderByDescending(x => salesmanTotals.ContainsKey(x.Salesman) ? salesmanTotals[x.Salesman] : 0m)
+                .ThenBy(x => x.CustomerCode)
+                .ToList();
+
+            var pagedSalesmen = sorted
+                .Select(x => x.Salesman)
+                .Distinct()
+                .Skip((req.Page - 1) * req.PageSize)
+                .Take(req.PageSize)
+                .ToHashSet();
+
+            var data = sorted.Where(x => pagedSalesmen.Contains(x.Salesman)).ToList();
+            var columnHeaders = GenerateSnapshotColumnHeaders(req);
+
+            return new OverdueAgingDetailWrapper
+            {
+                ColumnHeaders = columnHeaders,
+                Data = data
+            };
+        }
+
+        /// <summary>
+        /// 根据逾期天数确定账龄档位（使用Interval1-4作为天数边界）
+        /// </summary>
+        private static int GetSnapshotBucket(decimal overdueDays, OverdueAgingSnapshotReq req)
+        {
+            var days = (int)overdueDays;
+            if (days <= req.Interval1) return 1;
+            if (days <= req.Interval2) return 2;
+            if (days <= req.Interval3) return 3;
+            if (days <= req.Interval4) return 4;
+            return 5;
+        }
+
+        /// <summary>
+        /// 生成快照报表列头
+        /// </summary>
+        private static List<ColumnHeader> GenerateSnapshotColumnHeaders(OverdueAgingSnapshotReq req)
+        {
+            return new List<ColumnHeader>
+            {
+                new ColumnHeader { Field = "bucket1", HeaderName = $"0-{req.Interval1}天" },
+                new ColumnHeader { Field = "bucket2", HeaderName = $"{req.Interval1 + 1}-{req.Interval2}天" },
+                new ColumnHeader { Field = "bucket3", HeaderName = $"{req.Interval2 + 1}-{req.Interval3}天" },
+                new ColumnHeader { Field = "bucket4", HeaderName = $"{req.Interval3 + 1}-{req.Interval4}天" },
+                new ColumnHeader { Field = "bucket5", HeaderName = $"{req.Interval4 + 1}天+" }
+            };
+        }
+
+        #region 权限校验
+
+        /// <summary>
+        /// 快照报表权限校验（复用salereceivable模块权限）
+        /// </summary>
+        public async Task<(bool IsNoRight, int Code, string Message)> GetSnapshotPermission(OverdueAgingSnapshotReq req)
+        {
+            var loginContext = _auth.GetCurrentUser() ?? throw new CommonException(Define.LoginHasExpired, Define.INVALID_TOKEN);
+            var loginUser = loginContext.User;
+            var roles = loginContext.Roles.Select(x => x.Id).ToList();
+
+            var moduleElements = await GetSnapshotModuleElements(roles);
+
+            var domId = GetSnapshotModuleElementDomId(moduleElements);
+            switch (domId)
+            {
+                case view_all:
+                    break;
+                case view_dept:
+                    var deptResult = await HandleSnapshotDeptView(loginUser.User_Id, req);
+                    if (deptResult.HasError) return deptResult.Result;
+                    break;
+                case view_self:
+                    var selfResult = await HandleSnapshotSelfView(loginUser.User_Id, req);
+                    if (selfResult.HasError) return selfResult.Result;
+                    break;
+                default:
+                    return (true, 500, "用户角色未配置模块权限");
+            }
+
+            // 处理公司主体标识权限
+            var customQueryResult = await HandleCustomQueryPermission(req, moduleElements);
+            if (customQueryResult.IsNoRight)
+                return (customQueryResult.IsNoRight, customQueryResult.Code, customQueryResult.Message);
+
+            return (false, 200, string.Empty);
+        }
+
+        /// <summary>
+        /// 处理公司主体标识权限
+        /// </summary>
+        private async Task<(bool IsNoRight, int Code, string Message)> HandleCustomQueryPermission(OverdueAgingSnapshotReq req, List<ModuleElement> moduleElements)
+        {
+            var customQryCategory = await UnitWork.Find<Category>(x => x.TypeId == FinanceConsts.FICO_Custom_Query_Filter).ToListAsync();
+            var haveCustomQueryRight = customQryCategory.Select(x => x.DtCode).Intersect(moduleElements.Select(x => x.DomId)).Distinct().ToList();
+            if (haveCustomQueryRight.Count > 0)
+            {
+                var indicators = customQryCategory.Where(x => haveCustomQueryRight.Contains(x.DtCode)).Select(x => x.DtValue).ToList();
+                if (req.IndicatorList == null || (req.IndicatorList != null && req.IndicatorList.Count == 0))
+                {
+                    req.IndicatorList = indicators;
+                }
+                else if (req.IndicatorList.Except(indicators).Any())
+                {
+                    var invalidItems = req.IndicatorList.Where(x => !indicators.Contains(x)).ToList();
+                    var idcinfo = await UnitWork.Find<crm_oidc>(x => x.sbo_id == Define.SBO_ID).Where(x => invalidItems.Contains(x.Code)).Select(x => x.Name).ToListAsync();
+                    return (true, 500, $"无查看{string.Join("，", idcinfo)}标识的权限");
+                }
+                req.IndicatorList = req.IndicatorList.ConvertAll(i => i == Define.Non_IndicatorCode ? "N" : i);
+            }
+            else
+            {
+                var loginInfo = _auth.GetLoginInfo();
+                var loginIndicator = loginInfo.IndicateCode;
+                if (loginIndicator != Define.All_IndicatorCode)
+                {
+                    req.Indicator = loginIndicator == Define.Non_IndicatorCode ? "N" : loginIndicator;
+                    req.IndicatorList = new List<string>();
+                }
+                else
+                {
+                    req.Indicator = req.Indicator == Define.Non_IndicatorCode ? "N" : req.Indicator;
+                    if (req.IndicatorList != null)
+                        req.IndicatorList = req.IndicatorList.ConvertAll(i => i == Define.Non_IndicatorCode ? "N" : i);
+                }
+            }
+            return (false, 200, string.Empty);
+        }
+
+        /// <summary>
+        /// 获取salereceivable模块元素权限
+        /// </summary>
+        private async Task<List<ModuleElement>> GetSnapshotModuleElements(List<string> roleIds)
+        {
+            var modules = from m in UnitWork.Find<Module>(null)
+                          join r in UnitWork.Find<Relevance>(null) on m.Id equals r.SecondId
+                          join role in UnitWork.Find<Role>(null) on r.FirstId equals role.Id
+                          where r.Key == Define.ROLEMODULE && roleIds.Contains(r.FirstId) && m.Code == FinanceConsts.SalesInvoiceCode
+                          select new { m, roleId = role.Id };
+
+            return await (from me in UnitWork.Find<ModuleElement>(null)
+                          join r in UnitWork.Find<Relevance>(null) on me.Id equals r.SecondId
+                          join role in UnitWork.Find<Role>(null) on r.FirstId equals role.Id
+                          join mo in modules on new { roleId = role.Id, MId = me.ModuleId } equals new { mo.roleId, MId = mo.m.Id }
+                          where r.Key == Define.ROLEELEMENT && roleIds.Contains(r.FirstId)
+                          select me).ToListAsync();
+        }
+
+        /// <summary>
+        /// 获取当前有效的DomId
+        /// </summary>
+        private static string GetSnapshotModuleElementDomId(List<ModuleElement> elements)
+        {
+            if (elements.Exists(x => x.DomId == view_all)) return view_all;
+            if (elements.Exists(x => x.DomId == view_dept)) return view_dept;
+            return elements.Exists(x => x.DomId == view_self) ? view_self : null;
+        }
+
+        /// <summary>
+        /// 处理部门查看权限
+        /// </summary>
+        private async Task<(bool HasError, (bool, int, string) Result)> HandleSnapshotDeptView(int? userId, OverdueAgingSnapshotReq req)
+        {
+            if (!userId.HasValue) return (false, default);
+            var slpCode = await UnitWork.Find<sbo_user>(x =>
+                x.sbo_id == Define.SBO_ID && x.user_id == userId)
+                .Select(x => x.sale_id)
+                .FirstOrDefaultAsync();
+            if (!slpCode.HasValue) return (true, (true, 500, "未配置对应销售员"));
+            req.SlpCode = slpCode.Value.ToString();
+            var depId = _serviceBaseApp.GetSalesDepID(userId.Value);
+            var depIds = new List<string> { depId.ToString() };
+            req.SlpCodes = (await _serviceBaseApp.GetSboSlpCodeIds(depIds, Define.SBO_ID))
+                .Select(x => x.ToString()).ToList();
+            return (false, default);
+        }
+
+        /// <summary>
+        /// 处理个人查看权限
+        /// </summary>
+        private async Task<(bool HasError, (bool, int, string) Result)> HandleSnapshotSelfView(int? userId, OverdueAgingSnapshotReq req)
+        {
+            var slpCode = await UnitWork.Find<sbo_user>(x =>
+                x.sbo_id == Define.SBO_ID && x.user_id == userId)
+                .Select(x => x.sale_id)
+                .FirstOrDefaultAsync();
+            if (!slpCode.HasValue) return (true, (true, 500, "未配置对应销售员"));
+            req.SlpCode = slpCode.Value.ToString();
+            req.SlpCodes = new List<string> { slpCode.Value.ToString() };
+            return (false, default);
+        }
+
+        #endregion
+    }
+}
